import tempfile  # with the other imports

def write_json(path: Path, doc: dict, mode: int) -> None:
    fd, tmp = tempfile.mkstemp(dir=path.parent, prefix='.' + path.name + '.')
    try:
        os.fchmod(fd, mode)
        with os.fdopen(fd, 'w') as f:
            json.dump(doc, f, indent=1, sort_keys=True)
            f.write('\n')
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except FileNotFoundError:
            pass
        raise

import unicodedata

def _inert(text: str, keep_newlines: bool = False) -> str:
    """Visitor text for the operator's terminal: every non-printable or format character escaped."""
    out = []
    for c in text:
        if keep_newlines and c == "\n":
            out.append("\n    | ")
        elif c.isprintable() and unicodedata.category(c) not in ("Cf", "Cc"):
            out.append(c)
        else:
            out.append(c.encode("unicode_escape").decode("ascii"))
    return "".join(out)


