SAFE_URL = re.compile(r"https://[A-Za-z0-9.-]+(:\d+)?(/[A-Za-z0-9._~%/-]*)?(#[A-Za-z0-9._~-]*)?")
NETWORKS = {"esmeralda"}

def settings(cfg: dict, origin: str | None) -> dict:
    origin = (origin or cfg["public_origin"]).rstrip("/")
    if not re.fullmatch(r"https://[a-z0-9.-]+(:\d+)?|http://127\.0\.0\.1:\d+", origin):
        raise BuildError(f"origin must be https://host (or http://127.0.0.1:port for development): {origin}")
    network = cfg.get("network", "esmeralda")
    if network not in NETWORKS:
        raise BuildError(f"unknown network: {network!r}")
    repo = cfg.get("repo_url", "https://github.com/c7b/hidebox").rstrip("/")
    drop = cfg.get("security_drop_url") or ""
    for name, value in (("repo_url", repo), ("security_drop_url", drop)):
        if value and not SAFE_URL.fullmatch(value):
            raise BuildError(f"{name} must be a plain https URL: {value!r}")
    return {"ORIGIN": origin, "NETWORK": network.capitalize(),
            "SECURITY_DROP_URL": drop or origin + "/fine-print#report",
            "REPO_URL": repo, "BRAND": BRAND}

